package com.example.rokidgeminisecretary;
import android.app.*;import android.location.Address;import android.widget.*;import java.util.*;
/** A user-confirmed entrance destination, never a fabricated facility entrance. */
final class NavigationEntranceDialog {
 interface Selection{void use(String label,Address address);}
 static void show(Activity host,String destination,Selection selected){show(host,destination,selected,false);}
 static void showDestination(Activity host,String destination,Selection selected){show(host,destination,selected,true);}
 private static void show(Activity host,String destination,Selection selected,boolean general){
  LinearLayout body=new LinearLayout(host);body.setPadding(24,16,24,12);body.setOrientation(1);TextView hint=new TextView(host);hint.setText(general?"目的地を検索し、住所・座標を確認してください。候補を選ぶだけでは案内を開始しません。":"施設名・駅名に東口、正面入口などを加えて検索します。候補が施設の中心の場合もあるため、住所・座標を確認してください。選択だけでは案内を開始しません。");body.addView(hint);EditText query=new EditText(host);query.setSingleLine(true);query.setHint("例：東京駅 丸の内南口");query.setText(destination);body.addView(query);TextView status=new TextView(host);body.addView(status);
  AlertDialog dialog=new AlertDialog.Builder(host).setTitle(general?"変更先の候補を検索":"駅の出口・施設の入口").setView(body).setPositiveButton(general?"目的地を検索":"入口・出口を検索",null).setNegativeButton("閉じる",null).create();dialog.show();dialog.getButton(-1).setOnClickListener(v->{String text=query.getText().toString().trim();if(text.isEmpty()||text.length()>160){status.setText("入口・出口の名前を160文字以内で入力してください");return;}dialog.getButton(-1).setEnabled(false);status.setText("候補を取得中…");new Thread(()->{try{java.util.List<Address> choices=GoogleNavigationClient.enabled(host)?GoogleNavigationClient.searchPlaces(host,text):new android.location.Geocoder(host,Locale.JAPAN).getFromLocationName(text,5);host.runOnUiThread(()->{if(!dialog.isShowing()||host.isDestroyed())return;dialog.getButton(-1).setEnabled(true);if(choices==null||choices.isEmpty()){status.setText("候補がありません。入口の名前・地域を確認してください。施設の中心に自動で置き換えません。");return;}List<Address> valid=new ArrayList<>();List<String> names=new ArrayList<>();for(Address a:choices)if(a.hasLatitude()&&a.hasLongitude()&&Double.isFinite(a.getLatitude())&&Double.isFinite(a.getLongitude())&&Math.abs(a.getLatitude())<=90&&Math.abs(a.getLongitude())<=180){valid.add(a);names.add((a.getAddressLine(0)==null?text:a.getAddressLine(0))+"\n"+a.getLatitude()+", "+a.getLongitude());}if(valid.isEmpty()){status.setText("座標を確認できる入口候補がありません");return;}new AlertDialog.Builder(host).setTitle(general?"目的地の候補を確認":"入口・出口の候補を確認").setItems(names.toArray(new String[0]),(d,i)->new AlertDialog.Builder(host).setTitle(general?"この地点を変更先の候補にする":"この地点を入口・出口として使う").setMessage(names.get(i)+"\n実際の入口か確認してください。検索結果は入口を保証するものではありません。今の目的地の経路は開始しません。").setPositiveButton("目的地に設定",(confirm,w)->{if(!dialog.isShowing())return;selected.use(text+" / "+names.get(i).split("\\n")[0],valid.get(i));dialog.dismiss();}).setNegativeButton("戻る",null).show()).setNegativeButton("戻る",null).show();});}catch(Exception e){host.runOnUiThread(()->{if(dialog.isShowing()){dialog.getButton(-1).setEnabled(true);status.setText("候補を取得できません。通信・検索設定を確認してください");}});}},"LokiEntranceSearch").start();});
 }
 private NavigationEntranceDialog(){}
}
